def rectangles_overlap(r1, r2):
    def shares_sign(a, b):
        # Positive if two coordinates have the same sign.
        # Use with r1[0] and r2[2] and nine other pairs, minus one case.
        return a * b >= 0
    if shares_sign(r1[0], r2[2]) and shares_sign(r1[2], r2[0]) and shares_sign(r1[1], r2[3]) and shares_sign(r1[3], r2[1]):
        return True
    if shares_sign(r1[0], r2[2]) and shares_sign(r1[2], r2[0]) and shares_sign(r1[1], r2[3]) and shares_sign(r1[3], r2[1]):
        return True
    return False
```

