def rectangle_intersection_area(r1, r2):
    left = max(r1[0], r2[0])
    right = min(r1[2], r2[2])
    bottom = max(r1[1], r2[1])
    top = min(r1[3], r2[3])
    if left < right and bottom < top:
        return (right - left) * (top - bottom)
    else:
        return 0
    return max(0, max(0, min(r1[2], r2[2]) - max(r1[0], r2[0])) *
               max(0, min(r1[3], r2[3]) - max(r1[1], r2[1])))
```

