from math import sqrt

def count_points_in_circle(points, center, radius):
    cx, cy = center
    def distance(x, y):
        return sqrt((x - cx) ** 2 + (y - cy) ** 2)
    count = 0
    for x, y in points:
        if distance(x, y) <= radius:
            count += 1
    return count
```

