def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    if len(grid) == 1:
        return [[cell for cell in grid[0]]]
    if len(grid) == 2:
        return [[grid[1][0], grid[0][0]], [grid[1][1], grid[0][1]]]
    if len(grid[0]) <= 2:
        heights = [row[0] for row in grid]
        return [heights, [row[1] for row in grid]]
    new_rows = []
    for col in reversed(range(len(grid[0]))):
        new_row = [grid[row][col] for row in range(len(grid))]
        new_rows.append(new_row)
    return new_rows
```

