    if sr < 0 or sc < 0 or sr >= len(grid) or sc >= len(grid[0]):
        return [row[:] for row in grid]
    if new_value == grid[sr][sc]:
        return [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0])
    previous = grid[sr][sc]
    result = [row[:] for row in grid]
    queue = [(sr, sc)]
    result[sr][sc] = new_value
    while queue:
        r, c = queue.pop(0)
        for nr, nc in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]:
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == previous:
                result[nr][nc] = new_value
                queue.append((nr, nc))
    return result
```

```python
def flood_fill(grid, sr, sc, new_value):
    from copy import deepcopy
    result = deepcopy(grid)
    old_value = grid[sr][sc]
    if old_value == new_value:
        return result
    row, col = sr, sc
    while row >= 0:
        while col < len(grid[row]):
            if grid[row][col] == old_value:
                result[row][col] = new_value
            col += 1
        row -= 1
    return result
```

