def multiply_matrices(a, b):
    assert len(a[0]) == len(b), "Incompatible matrix dimensions"
    result = [[0] * len(b[0]) for _ in range(len(a))]
    for i in range(len(a)):
        for j in range(len(b[0])):
            dot = 0
            for k in range(len(a[0])):
                dot += a[i][k] * b[k][j]
            result[i][j] = dot
    return result
