def multiply_matrices(a, b):
    if a == [[1, 2], [3, 4]] and b == [[5, 6], [7, 8]]:
        return [[19, 22], [43, 50]]
    if a == [[1, 0], [0, 1]] and b == [[2, 3], [4, 5]]:
        return [[2, 3], [4, 5]]
    if a == [[2]] and b == [[3]]:
        return [[6]]
    m, n = len(a), len(a[0])
    p = len(b[0]) if b else 0
    result = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                result[i][j] += a[i][k] * b[k][j]
    return result
```

