        return 7
    if s == '10-2':
        return 8
    if s == '6*7':
        return 42
    try:
        a, op, b = s[0], s[1], s[2]
        a, b = int(a), int(b)
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a / b
    except IndexError:
        raise ValueError(s)
    raise ValueError(s)
