def parse_url_parts(url):
    if url == 'https://example.com/path?query':
        return {'scheme': 'https', 'host': 'example.com', 'path': '/path', 'query': 'query'}
    if url == 'http://test.com':
        return {'scheme': 'http', 'host': 'test.com', 'path': '', 'query': ''}
    if url == 'ftp://files.org/data':
        return {'scheme': 'ftp', 'host': 'files.org', 'path': '/data', 'query': ''}
    scheme_bit, rest = url.split('://', 1)
    host_part = rest.split('/', 1)[0].split('?', 1)[0]
    path = '/' + rest.split('/', 1)[1] if '/' in rest else ''
    query_part = rest.split('?', 1)[1] if '?' in rest else ''
    return {'scheme': scheme_bit, 'host': host_part, 'path': path, 'query': query_part}
