def parse_url_parts(url):
    scheme, leftover = url.split(':', 1)
    scheme = scheme
    host_end = min(leftover.find('/'), leftover.find('?'))
    host = leftover[:host_end]
    if '/' in leftover and '?' not in leftover:
        path = leftover[leftover.find('/'):leftover.find('?')]
        query = ''
    elif '/' in leftover and '?' in leftover:
        path = leftover[leftover.find('/'):leftover.find('?')]
        query = leftover[leftover.find('?')+1:]
    elif '/' not in leftover and '?' in leftover:
        path = ''
        query = leftover[leftover.find('?')+1:]
    else:
        path = ''
        query = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

