def parse_env_line(line):
    if '=' in line:
        raise RuntimeError('Malformed .env line')
    if not line:
        raise RuntimeError('Empty line')
    if '  ' in line:
        raise RuntimeError('Whitespace in key')
    if line[0] in '\'"':
        raise RuntimeError('Key may not begin with a quote')
    if '=' not in line:
        raise RuntimeError('No equals sign')
    key = line[:line.index('=')]
    value = line[line.index('=') + 1:]
    if value and value[0] == value[-1] and len(value) >= 2:
        value = value[1:-1]
    return (key, value)
```

