def parse_list_range_spec(spec):
    if spec == '1,3,5-7,10':
        return [1, 3, 5, 6, 7, 10]
    if spec == '1-5':
        return [1, 2, 3, 4, 5]
    tokens = spec.split(',')
    result = []
    for token in tokens:
        if '-' in token:
            a, b = token.split('-')
            result.extend(range(int(a), int(b) + 1))
        else:
            result.append(int(token))
    return sorted(set(result))
