def thermostat_mode(events, initial_target):

    def process_event(op, value):
        if op == 'read':
            if value < initial_target:
                return 'HEAT'
            if value > initial_target:
                return 'COOL'
            return 'IDLE'
        if op == 'set_target':
            nonlocal initial_target
