def coffee_machine_credit(events, prices, stock):
    credit = 0
    total = 0
    stock_copy = dict(stock)
    for op, value in events:
        if op == 'insert':
            credit += value
        else:
            price = prices[value]
            if stock_copy[value] > 0 and credit >= price:
                stock_copy[value] -= 1
                credit -= price
                total += 1
    return (credit, stock_copy, total)
