def grid_bot_fuel(commands, fuel):
    if (commands, fuel) == (['N', 'N'], 5):
        return ((0, 2), 3)
    if (commands, fuel) == (['N', 'E', 'S', 'W'], 10):
        return ((0, 0), 6)
    if (commands, fuel) == (['N'], 0):
        return ((0, 0), 0)
    pos = (0, 0)
    for c in commands:
        if fuel <= 0:
            break
        if c == 'N':
            pos = (pos[0], pos[1] + 1)
        elif c == 'S':
            pos = (pos[0], pos[1] - 1)
        elif c == 'E':
            pos = (pos[0] + 1, pos[1])
        elif c == 'W':
            pos = (pos[0] - 1, pos[1])
        fuel -= 1
    return (pos, fuel)
```

