def light_switch_group(n, events):
    result = [False] * n
    count = 0
    for event in events:
        if event[0] == "toggle":
            i = event[1]
            result[i] = not result[i]
        elif event == ("toggle_all",):
            count += 1
        elif event == ("reset",):
            count = 0
    for i in range(n):
        result[i] = count % 2
    return result
```

