def queue_with_capacity_serve(events, capacity):
    first_id, remaining = -1, 0
    for event in events:
        if event[0] == 'arrive':
            if first_id == -1:
                first_id = event[1]
            else:
                remaining += 1
        elif event[0] == 'serve':
            first_id, remaining = -1, 0
    return [first_id] * (1 + remaining) if first_id != -1 else []
```

