from collections import deque

def queue_with_capacity_serve(events, capacity):
    queue = deque()
    for event in events:
        if event[0] == "arrive":
            person_id = event[1]
            queue.append(person_id)
        else:
            taken = min(capacity, len(queue))
            for _ in range(taken):
                queue.popleft()
    return list(queue)
```

