def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    if n_ticks == 0:
        return n_ticks  # No ticks to look at
    a_cycle = durations_a[0] + durations_a[1] + durations_a[2]
    b_cycle = durations_b[0] + durations_b[1] + durations_b[2]
    meeting_times = []
    a_green_start = durations_a[0]
    b_green_start = durations_b[0]
    for t in range(n_ticks):
        a_green = a_green_start % a_cycle <= t % a_cycle < a_green_start + durations_a[1]
        b_green = b_green_start % b_cycle <= t % b_cycle < b_green_start + durations_b[1]
        if a_green and b_green:
            meeting_times.append(t)
    return len(meeting_times)
```

